1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID    string `json:"id"`
27		Name  string `json:"name"`
28		Price int64  `json:"price_fen"` // 固定单价，非负整数分，创建后不可修改
29	}
30	
31	type usageRecord struct {
32		ID         string `json:"id"`
33		CustomerID string `json:"customer_id"`
34		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
35		Quantity   int64  `json:"quantity"`
36	}
37	
38	type billLine struct {
39		UsageID  string `json:"usage_id"`
40		Time     string `json:"time"`
41		Quantity int64  `json:"quantity"`
42		LineFee  int64  `json:"line_fee_fen"`
43	}
44	
45	type bill struct {
46		ID         string     `json:"id"`
47		CustomerID string     `json:"customer_id"`
48		Month      string     `json:"month"` // YYYY-MM（UTC）
49		TotalQty   int64      `json:"total_quantity"`
50		UnitPrice  int64      `json:"unit_price_fen"`
51		TotalFee   int64      `json:"total_fee_fen"`
52		Lines      []billLine `json:"lines"`
53		CreatedAt  string     `json:"created_at"`
54	}
55	
56	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
57	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
58	type adjustment struct {
59		ID           string `json:"id"`
60		CustomerID   string `json:"customer_id"`
61		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
62		Amount       int64  `json:"amount_fen"`
63		Reason       string `json:"reason"`
64		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
65		CreatedAt    string `json:"created_at"`
66		Revoked      bool   `json:"revoked"`
67		RevokeReason string `json:"revoke_reason,omitempty"`
68		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
69		RevokedAt    string `json:"revoked_at,omitempty"`
70	}
71	
72	// payment 是对已结算账单的一笔实收登记（正整数分）。
73	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录，
74	// 撤销后该笔不再计入实收，也不会因重放而恢复。
75	type payment struct {
76		ID           string `json:"id"`
77		CustomerID   string `json:"customer_id"`
78		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
79		Amount       int64  `json:"amount_fen"`
80		Note         string `json:"note"`
81		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
82		CreatedAt    string `json:"created_at"`
83		Revoked      bool   `json:"revoked"`
84		RevokeReason string `json:"revoke_reason,omitempty"`
85		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
86		RevokedAt    string `json:"revoked_at,omitempty"`
87	}
88	
89	type state struct {
90		Version     int                     `json:"version"`
91		Customers   map[string]*customer    `json:"customers"`
92		Usage       map[string]*usageRecord `json:"usage"`       // 全局唯一用量标识 -> 记录
93		Bills       map[string]*bill        `json:"bills"`       // 客户 + "|" + 月份 -> 账单
94		Adjustments map[string]*adjustment  `json:"adjustments"` // 全局唯一调整标识 -> 记录
95		Payments    map[string]*payment     `json:"payments"`    // 全局唯一收款标识 -> 记录（与调整标识互不占用）
96		NextSeq     int64                   `json:"next_seq"`    // 已分配的最大操作序号（调整/撤销/收款共用）
97		path        string                  `json:"-"`
98	}
99	
100	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
101	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
102	func loadStore(dir string) (*state, error) {
103		p := filepath.Join(dir, "state.json")
104		data, err := os.ReadFile(p)
105		if err != nil {
106			if errors.Is(err, os.ErrNotExist) {
107				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
108					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
109				}
110				return newState(p), nil
111			}
112			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
113		}
114	
115		var s state
116		dec := json.NewDecoder(bytes.NewReader(data))
117		if err := dec.Decode(&s); err != nil {
118			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
119		}
120		// 拒绝尾部多余内容，避免静默吞掉异常数据。
121		if dec.More() {
122			return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
123		}
124		if err := s.validate(); err != nil {
125			return nil, fmt.Errorf("数据文件已损坏: %w", err)
126		}
127		// 旧版本数据文件没有 adjustments/payments/next_seq 字段：视为零调整、零实收。
128		if s.Adjustments == nil {
129			s.Adjustments = map[string]*adjustment{}
130		}
131		if s.Payments == nil {
132			s.Payments = map[string]*payment{}
133		}
134		s.path = p
135		return &s, nil
136	}
137	
138	func newState(p string) *state {
139		return &state{
140			Version:     stateVersion,
141			Customers:   map[string]*customer{},
142			Usage:       map[string]*usageRecord{},
143			Bills:       map[string]*bill{},
144			Adjustments: map[string]*adjustment{},
145			Payments:    map[string]*payment{},
146			path:        p,
147		}
148	}
149	
150	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
151	func (s *state) validate() error {
152		if s.Version != stateVersion {
153			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
154		}
155		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
156			return errors.New("缺少必要的数据节")
157		}
158		for id, c := range s.Customers {
159			if c == nil {
160				return fmt.Errorf("客户 %q 的数据为空", id)
161			}
162			if c.ID != id {
163				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
164			}
165			if c.ID == "" || c.Name == "" {
166				return fmt.Errorf("客户 %q 的标识或名称为空", id)
167			}
168			if c.Price < 0 {
169				return fmt.Errorf("客户 %q 单价为负", id)
170			}
171		}
172		for id, u := range s.Usage {
173			if u == nil {
174				return fmt.Errorf("用量 %q 的数据为空", id)
175			}
176			if u.ID != id {
177				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
178			}
179			if u.ID == "" {
180				return errors.New("存在空的用量标识")
181			}
182			if _, ok := s.Customers[u.CustomerID]; !ok {
183				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
184			}
185			if u.Quantity <= 0 {
186				return fmt.Errorf("用量 %q 的数量非正", u.ID)
187			}
188			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
189				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
190			}
191		}
192		for key, b := range s.Bills {
193			if b == nil {
194				return fmt.Errorf("账单 %q 的数据为空", key)
195			}
196			if billKey(b.CustomerID, b.Month) != key {
197				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
198			}
199			if _, ok := s.Customers[b.CustomerID]; !ok {
200				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
201			}
202			if !validMonth(b.Month) {
203				return fmt.Errorf("账单 %q 的月份无效", key)
204			}
205			if len(b.Lines) == 0 {
206				return fmt.Errorf("账单 %q 没有明细", key)
207			}
208			var qty, fee int64
209			for _, ln := range b.Lines {
210				u, ok := s.Usage[ln.UsageID]
211				if !ok {
212					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
213				}
214				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
215					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
216				}
217				if !inMonth(u.Time, b.Month) {
218					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
219				}
220				var err error
221				qty, err = add64(qty, ln.Quantity)
222				if err != nil {
223					return fmt.Errorf("账单 %q 汇总数量溢出", key)
224				}
225				fee, err = add64(fee, ln.LineFee)
226				if err != nil {
227					return fmt.Errorf("账单 %q 汇总金额溢出", key)
228				}
229			}
230			if qty != b.TotalQty {
231				return fmt.Errorf("账单 %q 总数量与明细不符", key)
232			}
233			if fee != b.TotalFee {
234				return fmt.Errorf("账单 %q 总金额与明细不符", key)
235			}
236			c := s.Customers[b.CustomerID]
237			for _, ln := range b.Lines {
238				lf, err := mul64(ln.Quantity, c.Price)
239				if err != nil {
240					return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
241				}
242				if lf != ln.LineFee {
243					return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
244				}
245			}
246			if b.UnitPrice != c.Price {
247				return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
248			}
249			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
250			// 而已入账记录理应全部在明细中）。
251			for _, u := range s.Usage {
252				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
253					found := false
254					for _, ln := range b.Lines {
255						if ln.UsageID == u.ID {
256							found = true
257							break
258						}
259					}
260					if !found {
261						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
262					}
263				}
264			}
265		}
266	
267		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
268		// 调整与收款共用同一个全局操作序号池，标识命名空间也互不占用。
269		if s.NextSeq < 0 {
270			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
271		}
272		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
273		for id, a := range s.Adjustments {
274			if _, clash := s.Payments[id]; clash {
275				return fmt.Errorf("标识 %q 同时被调整与收款占用", id)
276			}
277			if a == nil {
278				return fmt.Errorf("调整 %q 的数据为空", id)
279			}
280			if a.ID != id {
281				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
282			}
283			if a.ID == "" {
284				return errors.New("存在空的调整标识")
285			}
286			if a.Amount == 0 {
287				return fmt.Errorf("调整 %q 的金额为零", id)
288			}
289			if strings.TrimSpace(a.Reason) == "" {
290				return fmt.Errorf("调整 %q 的原因为空", id)
291			}
292			if !validMonth(a.Month) {
293				return fmt.Errorf("调整 %q 的月份无效", id)
294			}
295			if _, ok := s.Customers[a.CustomerID]; !ok {
296				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
297			}
298			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
299				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
300			}
301			if a.Seq < 1 || a.Seq > s.NextSeq {
302				return fmt.Errorf("调整 %q 的操作序号越界", id)
303			}
304			if prev, dup := seenSeq[a.Seq]; dup {
305				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
306			}
307			seenSeq[a.Seq] = "调整 " + id
308			if a.Revoked {
309				if strings.TrimSpace(a.RevokeReason) == "" {
310					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
311				}
312				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
313					return fmt.Errorf("调整 %q 的撤销序号越界", id)
314				}
315				if prev, dup := seenSeq[a.RevokeSeq]; dup {
316					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
317				}
318				seenSeq[a.RevokeSeq] = "撤销调整 " + id
319			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
320				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
321			}
322		}
323		for id, p := range s.Payments {
324			if _, clash := s.Adjustments[id]; clash {
325				return fmt.Errorf("标识 %q 同时被收款与调整占用", id)
326			}
327			if p == nil {
328				return fmt.Errorf("收款 %q 的数据为空", id)
329			}
330			if p.ID != id {
331				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
332			}
333			if p.ID == "" {
334				return errors.New("存在空的收款标识")
335			}
336			if p.Amount <= 0 {
337				return fmt.Errorf("收款 %q 的金额不是正整数", id)
338			}
339			if strings.TrimSpace(p.Note) == "" {
340				return fmt.Errorf("收款 %q 的备注为空", id)
341			}
342			if !validMonth(p.Month) {
343				return fmt.Errorf("收款 %q 的月份无效", id)
344			}
345			if _, ok := s.Customers[p.CustomerID]; !ok {
346				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
347			}
348			if _, ok := s.Bills[billKey(p.CustomerID, p.Month)]; !ok {
349				return fmt.Errorf("收款 %q 引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, p.Month)
350			}
351			if p.Seq < 1 || p.Seq > s.NextSeq {
352				return fmt.Errorf("收款 %q 的操作序号越界", id)
353			}
354			if prev, dup := seenSeq[p.Seq]; dup {
355				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
356			}
357			seenSeq[p.Seq] = "收款 " + id
358			if p.Revoked {
359				if strings.TrimSpace(p.RevokeReason) == "" {
360					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
361				}
362				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
363					return fmt.Errorf("收款 %q 的撤销序号越界", id)
364				}
365				if prev, dup := seenSeq[p.RevokeSeq]; dup {
366					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
367				}
368				seenSeq[p.RevokeSeq] = "撤销收款 " + id
369			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
370				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
371			}
372		}
373		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
374		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款之和）必须满足
375		// 0 ≤ 实收 ≤ 当前应付。越界说明金额与记录不一致。
376		for key, b := range s.Bills {
377			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
378			if err != nil {
379				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
380			}
381			received, err := paymentReceived(paymentsFor(s, b.CustomerID, b.Month))
382			if err != nil {
383				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
384			}
385			if received > payable {
386				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
387			}
388		}
389		return nil
390	}
391	
392	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
393	// 只有完整保存成功后调用方才会向用户报告成功。
394	func (s *state) save() error {
395		if err := s.validate(); err != nil {
396			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
397		}
398		data, err := json.MarshalIndent(s, "", "  ")
399		if err != nil {
400			return fmt.Errorf("序列化数据失败: %w", err)
401		}
402		data = append(data, '\n')
403	
404		tmp := s.path + ".tmp"
405		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
406		if err != nil {
407			return fmt.Errorf("写入临时数据文件失败: %w", err)
408		}
409		if _, err := f.Write(data); err != nil {
410			f.Close()
411			os.Remove(tmp)
412			return fmt.Errorf("写入临时数据文件失败: %w", err)
413		}
414		if err := f.Sync(); err != nil {
415			f.Close()
416			os.Remove(tmp)
417			return fmt.Errorf("同步数据文件失败: %w", err)
418		}
419		if err := f.Close(); err != nil {
420			os.Remove(tmp)
421			return fmt.Errorf("关闭数据文件失败: %w", err)
422		}
423		if err := os.Rename(tmp, s.path); err != nil {
424			os.Remove(tmp)
425			return fmt.Errorf("替换数据文件失败: %w", err)
426		}
427		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
428			dir.Sync()
429			dir.Close()
430		}
431		return nil
432	}
433	
434	func billKey(customerID, month string) string {
435		return customerID + "|" + month
436	}
437	
438	// sealed 报告某客户的指定月份是否已封账。
439	func (s *state) sealed(customerID, month string) bool {
440		_, ok := s.Bills[billKey(customerID, month)]
441		return ok
442	}
443	
444	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
445	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
446		var list []*adjustment
447		for _, a := range s.Adjustments {
448			if a.CustomerID == customerID && a.Month == month {
449				list = append(list, a)
450			}
451		}
452		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
453		return list
454	}
455	
456	// paymentsFor 返回某客户某月账单的全部收款，按操作序号升序。
457	func paymentsFor(s *state, customerID, month string) []*payment {
458		var list []*payment
459		for _, p := range s.Payments {
460			if p.CustomerID == customerID && p.Month == month {
461				list = append(list, p)
462			}
463		}
464		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
465		return list
466	}
467	
468	// paymentReceived 返回全部未撤销收款之和。各笔金额均为正整数，
469	// 用非负 64 位加法累加，溢出时返回错误。
470	func paymentReceived(pays []*payment) (int64, error) {
471		var received int64
472		for _, p := range pays {
473			if !p.Revoked {
474				var err error
475				received, err = add64(received, p.Amount)
476				if err != nil {
477					return 0, err
478				}
479			}
480		}
481		return received, nil
482	}
483	
484	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
485	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
486	
487	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
488	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
489	// [0, 有符号 64 位最大值] 内，全程整数运算。
490	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
491		var amounts []int64
492		for _, a := range adjs {
493			if !a.Revoked {
494				amounts = append(amounts, a.Amount)
495			}
496		}
497		net, err = sumSigned64(amounts...)
498		if err != nil {
499			return 0, 0, err
500		}
501		payable, err = addSigned64(b.TotalFee, net)
502		if err != nil {
503			return 0, 0, err
504		}
505		if payable < 0 {
506			return 0, 0, errPayableOutOfRange
507		}
508		return net, payable, nil
509	}
510

