157	func cmdUsageImport(dir, file string) error {
158		var reader io.ReadCloser
159		var source string
160		if file == "-" {
161			reader = io.NopCloser(os.Stdin)
162			source = "标准输入"
163		} else {
164			f, err := os.Open(file)
165			if err != nil {
166				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
167			}
168			reader = f
169			source = file
170		}
171		defer reader.Close()
172	
173		rows, parseErrs := parseUsageFile(reader)
174	
175		s, err := loadStore(dir)
176		if err != nil {
177			return err
178		}
179	
180		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
181		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
182		var problems []string
183		problems = append(problems, parseErrs...)
184	
185		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
186		var ordered []*parsedRow
187		newCount, dupCount := 0, 0
188	
189		for _, r := range rows {
190			cust, ok := s.Customers[r.rec.CustomerID]
191			if !ok {
192				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
193				continue
194			}
195			// 金额可行性预检：数量×固定单价不得溢出（金额单位：分）。
196			if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
197				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
198				continue
199			}
200	
201			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
202			var existing *usageRecord
203			if inStore, ok := s.Usage[r.rec.ID]; ok {
204				existing = inStore
205			} else if inBatch, ok := accepted[r.rec.ID]; ok {
206				existing = &inBatch.rec
207			}
208	
209			if existing != nil {
210				if !sameUsage(existing, &r.rec, r.t) {
211					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
212						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
213					continue
214				}
215				dupCount++
216				continue
217			}
218	
219			// 全新标识：不得进入该客户已封账的 UTC 自然月。
220			month := r.t.UTC().Format("2006-01")
221			if s.sealed(r.rec.CustomerID, month) {
222				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
223					r.line, r.rec.CustomerID, month, r.rec.ID))
224				continue
225			}
226	
227			rr := r
228			accepted[r.rec.ID] = rr
229			ordered = append(ordered, rr)
230			newCount++
231		}
232	
233		if len(problems) > 0 {
234			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
235		}
236	
237		for _, r := range ordered {
238			rec := r.rec
239			s.Usage[rec.ID] = &rec
240		}
241		if err := s.save(); err != nil {
242			return err
243		}
244		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
245		return nil
246	}
