248	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
249	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
250		cr := csv.NewReader(r)
251		cr.FieldsPerRecord = 4
252		cr.TrimLeadingSpace = true
253	
254		header, err := cr.Read()
255		if err == io.EOF {
256			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
257		}
258		if err != nil {
259			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
260		}
261		for i := range header {
262			header[i] = strings.TrimSpace(header[i])
263		}
264		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
265			header[2] != "time" || header[3] != "quantity" {
266			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
267		}
268	
269		var rows []*parsedRow
270		var problems []string
271		line := 1
272		for {
273			rec, err := cr.Read()
274			if err == io.EOF {
275				break
276			}
277			line++
278			if err != nil {
279				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
280				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
281					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
282					break
283				}
284				continue
285			}
286			for i := range rec {
287				rec[i] = strings.TrimSpace(rec[i])
288			}
289	
290			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
291			if id == "" {
292				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
293				continue
294			}
295			if custID == "" {
296				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
297				continue
298			}
299			t, err := time.Parse(time.RFC3339, ts)
300			if err != nil {
301				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
302				continue
303			}
304			qty, err := strconv.ParseInt(qtyText, 10, 64)
305			if err != nil {
306				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
307				continue
308			}
309			if qty <= 0 {
310				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
311				continue
312			}
313	
314			rows = append(rows, &parsedRow{
315				line: line,
316				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
317				t:    t,
318			})
319		}
320		return rows, problems
321	}
322	
323	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
324	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
325	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
326		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
327			return false
328		}
329		et, err := time.Parse(time.RFC3339, existing.Time)
330		if err != nil {
331			return existing.Time == candidate.Time
332		}
333		return et.Equal(candidateT)
334	}
335	
336	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
337	func validMonth(m string) bool {
338		t, err := time.Parse("2006-01", m)
339		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
340			return false
341		}
342		return true
343	}
344	
345	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
346	func inMonth(rfc3339, month string) bool {
347		t, err := time.Parse(time.RFC3339, rfc3339)
348		if err != nil {
349			return false
350		}
351		return t.UTC().Format("2006-01") == month
352	}
353	
354	func cmdBillSettle(dir, customerID, month string) error {
355		if !validMonth(month) {
356			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
357		}
358		s, err := loadStore(dir)
359		if err != nil {
360			return err
361		}
362		cust, ok := s.Customers[customerID]
363		if !ok {
364			return fmt.Errorf("客户标识 %q 不存在", customerID)
365		}
366	
367		key := billKey(customerID, month)
368		if existing, ok := s.Bills[key]; ok {
369			// 幂等：同一客户同一月份重复结算，直接返回原账单，
370			// 不重新计费、不产生新账单或调整、不落盘。
371			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
372			printBill(existing, cust, adjustmentsFor(s, customerID, month), paymentsFor(s, customerID, month))
373			return nil
374		}
375	
376		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
377		var inMonthRecs []*usageRecord
378		for _, u := range s.Usage {
379			if u.CustomerID == customerID && inMonth(u.Time, month) {
380				inMonthRecs = append(inMonthRecs, u)
381			}
382		}
383		if len(inMonthRecs) == 0 {
384			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
385		}
386		sortByInstant(inMonthRecs)
387	
388		lines := make([]billLine, 0, len(inMonthRecs))
389		var totalQty, totalFee int64
390		for _, u := range inMonthRecs {
391			lineFee, err := mul64(u.Quantity, cust.Price)
392			if err != nil {
393				return fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出，拒绝结算且不封账", u.ID, u.Quantity, cust.Price)
394			}
395			totalQty, err = add64(totalQty, u.Quantity)
396			if err != nil {
397				return fmt.Errorf("汇总数量溢出有符号 64 位整数范围，拒绝结算且不封账")
398			}
399			totalFee, err = add64(totalFee, lineFee)
400			if err != nil {
401				return fmt.Errorf("汇总金额溢出有符号 64 位整数范围，拒绝结算且不封账")
402			}
403			lines = append(lines, billLine{
404				UsageID:  u.ID,
405				Time:     u.Time,
406				Quantity: u.Quantity,
407				LineFee:  lineFee,
408			})
409		}
410	
411		b := &bill{
412			ID:         stableBillID(customerID, month),
413			CustomerID: customerID,
414			Month:      month,
415			TotalQty:   totalQty,
416			UnitPrice:  cust.Price,
417			TotalFee:   totalFee,
418			Lines:      lines,
419			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
420		}
421		s.Bills[key] = b
422	
423		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
424		if err := s.save(); err != nil {
425			delete(s.Bills, key)
426			return err
427		}
428		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
429		printBill(b, cust, nil, nil)
430		return nil
431	}
432	
433	func cmdBillShow(dir, customerID, month string) error {
434		if !validMonth(month) {
435			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
436		}
437		s, err := loadStore(dir)
438		if err != nil {
439			return err
440		}
441		cust, ok := s.Customers[customerID]
442		if !ok {
443			return fmt.Errorf("客户标识 %q 不存在", customerID)
444		}
445		b, ok := s.Bills[billKey(customerID, month)]
446		if !ok {
447			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
448		}
449		printBill(b, cust, adjustmentsFor(s, customerID, month), paymentsFor(s, customerID, month))
450		return nil
451	}
452	
453	func sortByInstant(us []*usageRecord) {
454		// 入参时间均已在载入/导入时校验为 RFC3339。
455		sort.Slice(us, func(i, j int) bool {
456			ti, _ := time.Parse(time.RFC3339, us[i].Time)
457			tj, _ := time.Parse(time.RFC3339, us[j].Time)
458			ui, uj := ti.UTC(), tj.UTC()
459			if !ui.Equal(uj) {
460				return ui.Before(uj)
461			}
462			return us[i].ID < us[j].ID
463		})
464	}
465	
466	// stableBillID 由（客户标识，月份）确定性派生：跨进程稳定，且客户/月份间唯一。
467	func stableBillID(customerID, month string) string {
468		sum := sha256.Sum256([]byte(customerID + "\x00" + month))
469		return "BILL-" + hex.EncodeToString(sum[:])[:16]
470	}
471	
472	func printBill(b *bill, cust *customer, adjs []*adjustment, pays []*payment) {
473		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
474		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
475		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
476		fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
477		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
478		fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
479		// 数据在载入时已校验一致，此处计算不会出错。
480		net, payable, _ := billTotals(b, adjs)
481		received, _ := paymentReceived(pays)
482		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
483		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
484		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
485		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
486		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
487		fmt.Fprintln(stdout, "明细：")
488		for i, ln := range b.Lines {
489			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
490				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
491		}
492		if len(adjs) == 0 {
493			fmt.Fprintln(stdout, "调整与撤销历史：无")
494		} else {
495			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
496			for i, ev := range historyEvents(adjs) {
497				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
498			}
499		}
500		if len(pays) == 0 {
501			fmt.Fprintln(stdout, "收款与撤销历史：无")
502		} else {
503			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
504			for i, ev := range paymentHistoryEvents(pays) {
505				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
506			}
507		}
508	}
