510	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
511	func historyEvents(adjs []*adjustment) []string {
512		type event struct {
513			seq  int64
514			text string
515		}
516		var events []event
517		for _, a := range adjs {
518			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
519				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
520			if a.Revoked {
521				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
522					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
523			}
524		}
525		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
526		out := make([]string, len(events))
527		for i, ev := range events {
528			out[i] = ev.text
529		}
530		return out
531	}
