590	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
591		if !validMonth(month) {
592			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
593		}
594		if strings.TrimSpace(adjID) == "" {
595			return fmt.Errorf("调整标识不能为空")
596		}
597		amount, err := parseAmount(amountText)
598		if err != nil {
599			return err
600		}
601		if strings.TrimSpace(reason) == "" {
602			return fmt.Errorf("调整原因不能为空")
603		}
604	
605		s, err := loadStore(dir)
606		if err != nil {
607			return err
608		}
609		if _, ok := s.Customers[customerID]; !ok {
610			return fmt.Errorf("客户标识 %q 不存在", customerID)
611		}
612		b, ok := s.Bills[billKey(customerID, month)]
613		if !ok {
614			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
615		}
616	
617		if existing, ok := s.Adjustments[adjID]; ok {
618			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
619			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
620			if existing.CustomerID == customerID && existing.Month == month &&
621				existing.Amount == amount && existing.Reason == reason {
622				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
623				printAdjustment(existing, s)
624				return nil
625			}
626			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
627				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
628		}
629		// 调整标识与收款标识共用全局命名空间，互不占用。
630		if clash, isPay := s.Payments[adjID]; isPay {
631			return fmt.Errorf("调整标识 %q 已被收款占用（客户 %s 月份 %s），调整标识与收款标识互不占用",
632				adjID, clash.CustomerID, clash.Month)
633		}
634	
635		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
636		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
637		// 不占用该调整标识。
638		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
639		if err != nil {
640			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
641		}
642		received, err := paymentReceived(paymentsFor(s, customerID, month))
643		if err != nil {
644			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
645		}
646		newPayable, err := addSigned64(payable, amount)
647		if err != nil {
648			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
649		}
650		if newPayable < 0 {
651			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
652		}
653		if newPayable < received {
654			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
655				newPayable, received, payable, amount)
656		}
657	
658		a := &adjustment{
659			ID:         adjID,
660			CustomerID: customerID,
661			Month:      month,
662			Amount:     amount,
663			Reason:     reason,
664			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
665		}
666		s.NextSeq++
667		a.Seq = s.NextSeq
668		s.Adjustments[adjID] = a
669	
670		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
671		// 该调整标识不被占用。
672		if err := s.save(); err != nil {
673			delete(s.Adjustments, adjID)
674			s.NextSeq--
675			return err
676		}
677		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
678			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
679		printAdjustment(a, s)
680		return nil
681	}
