683	func cmdBillRevoke(dir, adjID, reason string) error {
684		if strings.TrimSpace(adjID) == "" {
685			return fmt.Errorf("调整标识不能为空")
686		}
687		if strings.TrimSpace(reason) == "" {
688			return fmt.Errorf("撤销原因不能为空")
689		}
690	
691		s, err := loadStore(dir)
692		if err != nil {
693			return err
694		}
695		a, ok := s.Adjustments[adjID]
696		if !ok {
697			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
698		}
699	
700		if a.Revoked {
701			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
702			// 改用其他原因则拒绝。
703			if a.RevokeReason == reason {
704				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
705				printAdjustment(a, s)
706				return nil
707			}
708			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
709		}
710	
711		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
712		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
713		// 改变余额后重试。
714		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
715		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
716		if err != nil {
717			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
718		}
719		received, err := paymentReceived(paymentsFor(s, a.CustomerID, a.Month))
720		if err != nil {
721			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
722		}
723		neg, err := neg64(a.Amount)
724		if err != nil {
725			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
726		}
727		newPayable, err := addSigned64(payable, neg)
728		if err != nil {
729			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
730				payable, a.Amount)
731		}
732		if newPayable < 0 {
733			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
734				newPayable, payable, a.Amount)
735		}
736		if newPayable < received {
737			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
738				newPayable, received, payable, a.Amount)
739		}
740	
741		a.Revoked = true
742		a.RevokeReason = reason
743		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
744		s.NextSeq++
745		a.RevokeSeq = s.NextSeq
746	
747		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
748		if err := s.save(); err != nil {
749			a.Revoked = false
750			a.RevokeReason = ""
751			a.RevokedAt = ""
752			a.RevokeSeq = 0
753			s.NextSeq--
754			return err
755		}
756		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
757			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
758		printAdjustment(a, s)
759		return nil
760	}
