762	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
763	func printAdjustment(a *adjustment, s *state) {
764		b := s.Bills[billKey(a.CustomerID, a.Month)]
765		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
766		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
767		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
768		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
769		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
770		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
771		if a.Revoked {
772			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
773		} else {
774			fmt.Fprintf(stdout, "当前状态：生效中\n")
775		}
776		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
777	}
