779	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
780	func parsePositiveAmount(text string) (int64, error) {
781		text = strings.TrimSpace(text)
782		amount, err := strconv.ParseInt(text, 10, 64)
783		if err != nil {
784			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
785		}
786		if amount <= 0 {
787			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
788		}
789		return amount, nil
790	}
