792	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
793		if !validMonth(month) {
794			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
795		}
796		if strings.TrimSpace(payID) == "" {
797			return fmt.Errorf("收款标识不能为空")
798		}
799		amount, err := parsePositiveAmount(amountText)
800		if err != nil {
801			return err
802		}
803		if strings.TrimSpace(note) == "" {
804			return fmt.Errorf("收款备注不能为空")
805		}
806	
807		s, err := loadStore(dir)
808		if err != nil {
809			return err
810		}
811		if _, ok := s.Customers[customerID]; !ok {
812			return fmt.Errorf("客户标识 %q 不存在", customerID)
813		}
814		b, ok := s.Bills[billKey(customerID, month)]
815		if !ok {
816			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, month)
817		}
818		// 收款标识与调整标识共用全局命名空间，互不占用。
819		if clash, isAdj := s.Adjustments[payID]; isAdj {
820			return fmt.Errorf("收款标识 %q 已被调整占用（客户 %s 月份 %s），收款标识与调整标识互不占用",
821				payID, clash.CustomerID, clash.Month)
822		}
823	
824		pays := paymentsFor(s, customerID, month)
825		adjs := adjustmentsFor(s, customerID, month)
826		_, payable, err := billTotals(b, adjs)
827		if err != nil {
828			return fmt.Errorf("账单当前应付异常，拒绝登记收款: %w", err)
829		}
830		received, err := paymentReceived(pays)
831		if err != nil {
832			return fmt.Errorf("实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", err)
833		}
834	
835		if existing, ok := s.Payments[payID]; ok {
836			// 相同标识按客户、月份、金额、备注判断重复：内容相同返回已保存
837			// 记录，不再次增加实收；已撤销的重放仍返回已撤销状态，不恢复实收。
838			if existing.CustomerID == customerID && existing.Month == month &&
839				existing.Amount == amount && existing.Note == note {
840				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
841				printPayment(existing, s)
842				return nil
843			}
844			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 备注=%q），拒绝复用",
845				payID, existing.CustomerID, existing.Month, existing.Amount, existing.Note)
846		}
847	
848		if payable == 0 {
849			return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, month)
850		}
851		// 超过未收余额的登记拒绝（实收始终 ≤ 当前应付）。
852		if amount > payable-received {
853			return fmt.Errorf("收款 %d 分超过未收余额 %d 分（当前应付 %d 分，实收 %d 分），拒绝登记",
854				amount, payable-received, payable, received)
855		}
856	
857		p := &payment{
858			ID:         payID,
859			CustomerID: customerID,
860			Month:      month,
861			Amount:     amount,
862			Note:       note,
863			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
864		}
865		s.NextSeq++
866		p.Seq = s.NextSeq
867		s.Payments[payID] = p
868	
869		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
870		// 一切不生效，该收款标识不被占用。
871		if err := s.save(); err != nil {
872			delete(s.Payments, payID)
873			s.NextSeq--
874			return err
875		}
876		fmt.Fprintf(stdout, "已登记收款 %q，客户 %s 的 %s 实收 %d 分（%s），未收余额 %d 分（%s）：\n\n",
877			payID, customerID, month, received+amount, moneyFen(received+amount),
878			payable-received-amount, moneyFen(payable-received-amount))
879		printPayment(p, s)
880		return nil
881	}
