883	func cmdBillUnpay(dir, payID, reason string) error {
884		if strings.TrimSpace(payID) == "" {
885			return fmt.Errorf("收款标识不能为空")
886		}
887		if strings.TrimSpace(reason) == "" {
888			return fmt.Errorf("撤销原因不能为空")
889		}
890	
891		s, err := loadStore(dir)
892		if err != nil {
893			return err
894		}
895		p, ok := s.Payments[payID]
896		if !ok {
897			// 即便标识恰好是调整标识，也明确提示不存在收款目标。
898			if _, isAdj := s.Adjustments[payID]; isAdj {
899				return fmt.Errorf("收款标识 %q 不存在（该标识属于调整记录），无法撤销收款", payID)
900			}
901			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
902		}
903	
904		if p.Revoked {
905			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
906			// 改用其他原因则拒绝。
907			if p.RevokeReason == reason {
908				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
909				printPayment(p, s)
910				return nil
911			}
912			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
913		}
914	
915		// 撤销只取消该笔实收，不改变应付、其他收款或调整。
916		p.Revoked = true
917		p.RevokeReason = reason
918		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
919		s.NextSeq++
920		p.RevokeSeq = s.NextSeq
921	
922		b := s.Bills[billKey(p.CustomerID, p.Month)] // 载入时已校验存在
923		_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, p.Month))
924		received, _ := paymentReceived(paymentsFor(s, p.CustomerID, p.Month))
925	
926		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
927		if err := s.save(); err != nil {
928			p.Revoked = false
929			p.RevokeReason = ""
930			p.RevokedAt = ""
931			p.RevokeSeq = 0
932			s.NextSeq--
933			return err
934		}
935		fmt.Fprintf(stdout, "已撤销收款 %q（%d 分），客户 %s 的 %s 实收 %d 分（%s），未收余额 %d 分（%s）：\n\n",
936			payID, p.Amount, p.CustomerID, p.Month, received, moneyFen(received),
937			payable-received, moneyFen(payable-received))
938		printPayment(p, s)
939		return nil
940	}
941	
942	// printPayment 输出单笔收款记录及其当前状态；应付/实收取自当前库状态。
943	func printPayment(p *payment, s *state) {
944		b := s.Bills[billKey(p.CustomerID, p.Month)]
945		_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, p.Month))
946		received, _ := paymentReceived(paymentsFor(s, p.CustomerID, p.Month))
947		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
948		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
949		fmt.Fprintf(stdout, "月份：%s\n", p.Month)
950		fmt.Fprintf(stdout, "收款金额：%d 分（%s）\n", p.Amount, moneyFen(p.Amount))
951		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
952		if p.Revoked {
953			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
954		} else {
955			fmt.Fprintf(stdout, "当前状态：实收中\n")
956		}
957		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
958		fmt.Fprintf(stdout, "实收合计：%d 分（%s）\n", received, moneyFen(received))
959		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", payable-received, moneyFen(payable-received))
960	}
