	}

	// 重复结算不创建账单或调整，返回含调整历史的原账单。
	again := h.mustRun("bill", "settle", "c1", "2026-09")
	if !strings.Contains(again, "幂等") || !strings.Contains(again, "当前应付：1200 分") ||
		!strings.Contains(again, "调整 adj-1") {
